package com.gamehub.application.controller;
import com.gamehub.application.OperationsService; import java.util.List;
public final class RegistrationController { private final OperationsService ops; public RegistrationController(OperationsService ops){this.ops=ops;} public List<String> tournaments()throws Exception{return ops.tournaments();} public List<String> registrations(long tournament)throws Exception{return ops.registrations(tournament);} public List<String> teams(long captain)throws Exception{return ops.captainTeams(captain);} public long registerSolo(long tournament,long customer)throws Exception{return ops.registerTournament(tournament,customer);} public long registerTeam(long tournament,long captain,long team)throws Exception{return ops.registerTournamentTeam(tournament,captain,team);} }